\State \hskip2em $\Delta_2 = \mathit{latency}(\mathcal{GC}_2) \cdot \delta$ \BlueComment{$\mathit{latency}(\mathcal{GC}_2)$ denotes the number of asynchronous rounds of $\mathcal{GC}_2$ (see \Cref{section:preliminaries})}
\State \hskip2em $\Delta_{\mathit{sync}} = \Delta_{\mathit{shift}} + \delta$ 
\State \hskip2em $\mathcal{B} = \mathit{pbit}(\mathcal{A}^S)$ \BlueComment{$\mathcal{B}$ denotes the per-process bit complexity of $\mathcal{A}^S$ (see \Cref{section:preliminaries})}
\State \hskip2em $\mathcal{R} = \mathit{latency}(\mathcal{A}^S)$ \BlueComment{$\mathcal{R}$ denotes the number of synchronous rounds of $\mathcal{A}^S$ (see \Cref{section:preliminaries})}

\medskip
\State \textbf{Parameters:}
\State \hskip2em $\Delta_{\mathit{shift}}$ = any value (configurable) \label{line:delta_shift}

