\State \textbf{Task 1:}
\State \hskip2em \textbf{When to start:} upon an invocation of a $\mathsf{propose}(v \in \mathsf{Value})$ request \label{line:start_task_1}

\smallskip
\State \hskip2em \textbf{Steps:}
\State \hskip4em 1) Process $p_i$ proposes $v$ to $\mathcal{GC}_1$. Process $p_i$ runs $\mathcal{GC}_1$ until (1) $\Delta_{\mathit{shift}} + \Delta_1$ time has elapsed since $p_i$ proposed, and (2) $p_i$ decides from \hphantom{aaaaaaaaaaa}$\mathcal{GC}_1$.
