\smallskip
\State \hskip4em 7) Process $p_i$ triggers $\mathsf{completed}$. \BlueComment{process $p_i$ completes \block} \label{line:step_complete}

\medskip
\State \textbf{Task 2:}
\State \hskip2em \textbf{When to start:} upon an invocation of an $\mathsf{abandon}$ request \label{line:start_task_2}
\State \hskip2em \textbf{Steps:}
