\section{\block's Correctness \& Complexity: Formal Proof}\label{section:crux_correctness_complexity_formal}

\smallskip
\noindent \textbf{Simulating cryptography-free $\mathcal{A}^S$.}
We explicitly define our simulation $\mathsf{CryptoFreeSim}$ in \Cref{algorithm:crypto_free_sim}.

\begin{algorithm}
\caption{$\mathsf{CryptoFreeSim}$: Pseudocode (for process $p_i$)}
\label{algorithm:crypto_free_sim}
\footnotesize
\begin{algorithmic} [1] 
\State \textbf{Local variables:}
\State \hskip2em $\mathsf{Local\_State}$ $s_i \gets$ the initial state corresponding to $p_i$'s proposal to $\mathcal{A}^S$
\State \hskip2em $\mathsf{Integer}$ $\mathit{round}_i \gets 1$
\State \hskip2em $\mathsf{Integer}$ $\mathit{sent\_bits}_i \gets 0$
\State \hskip2em $\mathsf{Set}(\mathsf{Message})$ $\mathit{received}_i \gets \emptyset$ \BlueComment{received messages are stored here}

\medskip
\State \textbf{while} $\mathit{round}_i \leq \mathcal{R}$:
\State \hskip2em \textbf{for each} $\mathsf{Process}$ $p_j$:
\State \hskip4em let $M_j \gets$ the messages $\mathcal{A}^S$ instructs $p_i$ to send to $p_j$ when $p_i$'s local state is $s_i$
\State \hskip4em let $B_j \gets$ the number of bits in $M_j$
\State \hskip4em \textbf{if} $M_j \neq \bot$: \BlueComment{there exists a message to be sent to $p_j$}
\State \hskip6em \textbf{if} $\mathit{sent\_bits}_i + B_j \leq 2\mathcal{B}$:   \label{line:check_sent_messages_crypto_free} \BlueComment{$p_i$ can still send messages}
\State \hskip8em send $\langle \mathit{round}_i \text{ mod } 2, M_j \rangle$ to $p_j$ \BlueComment{$p_i$ sends $M_j$ to process $p_j$ with the parity bit $\mathit{round}_i \text{ mod } 2$}
\State \hskip8em $\mathit{sent\_bits}_i \gets \mathit{sent\_bits}_i + B_j$

\medskip
\State \hskip2em \textbf{wait for} $\Delta_{\mathit{sync}} = \Delta_{\mathit{shift}} + \delta$ time

\medskip
\State \hskip2em let $\mathit{received\_current\_round} \gets $ every message $m$ that belongs to $\mathit{received}_i$ with the parity bit $\mathit{round}_i \text{ mod } 2$
\State \hskip2em $s_i \gets$ the state $\mathcal{A}^S$ instructs $p_i$ to transit to based on (1) $p_i$'s previous state $s_i$, and (2) $\mathit{received\_current\_round}$ 
\State \hskip2em $\mathit{round}_i \gets \mathit{round}_i + 1$
\end{algorithmic} 
\end{algorithm}

In the rest of the proof, we say that ``$\mathcal{S}^*$ holds'' if and only if (1) the first correct process that starts $\mathsf{CryptoFreeSim}$ does so at some time $\tau^* \geq \text{GST}$, (2) all correct processes start $\mathsf{CryptoFreeSim}$ by time $\tau^* + \Delta_{\mathit{shift}}$, and (3) no correct process stops $\mathsf{CryptoFreeSim}$ by time $\tau^* + \mathcal{R}(\Delta_{\mathit{shift}} + \delta) = \tau^* + \mathcal{R} \cdot \Delta_{\mathit{sync}}$.

\begin{lemma}[$\mathsf{CryptoFreeSim}$ simulates $\mathcal{A}^S$] \label{lemma:cryptography_free_simulation_correct}
Let $\mathcal{S}^*$ hold.
For each execution $\mathcal{E}$ of $\mathsf{CryptoFreeSim}$, there exists an $\mathcal{R}$-rounds-long synchronous execution $\mathcal{E}'$ of $\mathcal{A}^S$ such that:
\begin{compactitem}
    \item the sets of correct processes in $\mathcal{E}$ and $\mathcal{E}'$ are identical, and

    \item the proposals of correct processes in $\mathcal{E}$ and $\mathcal{E}'$ are identical, and

    \item the sets of messages sent by correct processes in $\mathcal{E}$ and $\mathcal{E}'$ are identical (modulo the parity bits), and

    \item for each correct process $p_i$ and every $k \in [1, \mathcal{R} + 1]$, $s_i^k(\mathcal{E}) = s_i^k(\mathcal{E}')$, where (1) $s_i^k(\mathcal{E})$ is the state of $p_i$ at the beginning of the $k$-th (i.e., at the end of the $(k - 1)$-st) simulated round in $\mathcal{E}$, and (2) $s_i^k(\mathcal{E}')$ is the state of $p_i$ at the beginning of the $k$-th (i.e., at the end of the $(k - 1)$-st) round in $\mathcal{E}'$.
\end{compactitem}    
\end{lemma}

\smallskip
\noindent \textbf{Simulating cryptography-based $\mathcal{A}^S$.}
$\mathsf{CryptoSim}$ (\Cref{algorithm:simulation}) represents our simulation of a cryptography-based synchronous algorithm $\mathcal{A}^S$ (Step 2 of Task 1).

\begin{algorithm}
\caption{$\mathsf{CryptoSim}$: Pseudocode (for process $p_i$)}
\label{algorithm:simulation}
\footnotesize
\begin{algorithmic} [1] 
\State \textbf{Local variables:}
\State \hskip2em $\mathsf{Local\_State}$ $s_i \gets$ the initial state corresponding to $p_i$'s proposal to $\mathcal{A}^S$
\State \hskip2em $\mathsf{Integer}$ $\mathit{round}_i \gets 1$
\State \hskip2em $\mathsf{Integer}$ $\mathit{sent\_bits}_i \gets 0$
\State \hskip2em $\mathsf{Set}(\mathsf{Message})$ $\mathit{received}_i \gets \emptyset$

\medskip
\State \textbf{while} $\mathit{round}_i \leq \mathcal{R}$:
\State \hskip2em $\mathit{received}_i \gets \emptyset$
\State \hskip2em \textbf{measure} $\Delta_{\mathit{sync}} = 2\Delta_{\mathit{shift}} + \delta$ time 
\State \hskip2em for every message $m$ received in the following $\Delta_{\mathit{sync}} = 2\Delta_{\mathit{shift}} + \delta$ time period, add $m$ to $\mathit{received}_i$ \label{line:receive_simulation}

\medskip
\State \hskip2em \textbf{wait for} $\Delta_{\mathit{shift}}$ time
\State \hskip2em \textbf{for each} $\mathsf{Process}$ $p_j$:
\State \hskip4em let $M_j \gets$ the messages $\mathcal{A}^S$ instructs $p_i$ to send to $p_j$ when $p_i$'s local state is $s_i$
\State \hskip4em let $B_j \gets$ the number of bits in $M_j$
\State \hskip4em \textbf{if} $M_j \neq \bot$: \BlueComment{there exists a message to be sent to $p_j$}
\State \hskip6em \textbf{if} $\mathit{sent\_bits}_i + B_j \leq \mathcal{B}$:  \BlueComment{$p_i$ can still send messages} \label{line:check_sent_bits}
\State \hskip8em send $\langle M_j \rangle$ to $p_j$ \label{line:send_simulation} \BlueComment{$p_i$ sends $M_j$ to process $p_j$}
\State \hskip8em $\mathit{sent\_bits}_i \gets \mathit{sent\_bits}_i + B_j$

\medskip
\State \hskip2em \textbf{upon} the measured $\Delta_{\mathit{sync}} = 2\Delta_{\mathit{shift}} + \delta$ time elapses:
